def update_group(group, other, nxt):
    n = len(group)
    i = 0
    while i < n:
        j = i
        val = other[group[i]]
        while j + 1 < n and other[group[j+1]] == val:
            j += 1
        if j + 1 < n:
            cand = group[j+1]
            for pos in range(i, j+1):
                idx = group[pos]
                if cand < nxt[idx]:
                    nxt[idx] = cand
        i = j + 1

