class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        if not queries:
            return 0

        max_r = max(r for _, r in queries)

        # powers[i] = 4^i
        powers = [1]
        while powers[-1] <= max_r:
            powers.append(powers[-1] * 4)

        # full_sum[i] = sum of required divisions for all x in [1, 4^i - 1]
        full_sum = [0] * len(powers)
        for i in range(1, len(powers)):
            full_sum[i] = full_sum[i - 1] + i * (powers[i] - powers[i - 1])

        def prefix(n: int) -> int:
            """Sum of required divisions for all x in [1, n]."""
            if n <= 0:
                return 0
            # Required divisions for x is its number of base-4 digits.
            k = (n.bit_length() + 1) // 2
            return full_sum[k - 1] + k * (n - powers[k - 1] + 1)

        ans = 0
        for l, r in queries:
            total_divisions = prefix(r) - prefix(l - 1)
            max_divisions = (r.bit_length() + 1) // 2
            ans += max(max_divisions, (total_divisions + 1) // 2)

        return ans

