def main() -> None:
    it = iter(map(int, sys.stdin.buffer.read().split()))
    try:
        N = next(it)
    except StopIteration:
        return
    M = next(it)

    adj = [[] for _ in range(N)]
    for _ in range(M):
        u = next(it) - 1
        v = next(it) - 1
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * N

    # i: isolated vertices
    # o: non-isolated odd-size components
    # a: even-size components with both color classes even
    # b: even-size components with both color classes odd
    i = o = a = b = 0

    for s in range(N):
        if color[s] != -1:
            continue

        color[s] = 0
        cnt0, cnt1 = 1, 0
        stack = [s]

        while stack:
            u = stack.pop()
            cu = color[u]
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = cu ^ 1
                    if color[v] == 0:
                        cnt0 += 1
                    else:
                        cnt1 += 1
                    stack.append(v)

        x, y = cnt0, cnt1
        size = x + y

        if size == 1:
            i += 1
        elif size & 1:
            o += 1
        else:
            if (x & 1) and (y & 1):
                b += 1
            else:
                a += 1

    # If N is odd, every terminal complete bipartite graph has an even number
    # of edges, so the parity of the total number of moves is just M mod 2.
    if N & 1:
        print("Aoki" if (M & 1) else "Takahashi")
        return

    # For even N, compute the skeleton game value F (for S = 0).
    if o > 0:
        F = 1
    else:
        # Here all odd components are isolated, so i is even.
        if i == 0:
            F = 0
        elif a > 0:
            F = 1
        elif b >= 2:
            F = 1
        elif b == 1:
            F = 1 if i == 2 else 0
        else:  # b == 0
            F = 1 if (i == 2 or i >= 6) else 0

    # Parity of currently missing internal edges:
    # S = sum(a_i * b_i - e_i), and a_i*b_i is odd exactly for type b components.
    S_parity = (b & 1) ^ (M & 1)

    win = S_parity ^ F
    print("Aoki" if win else "Takahashi")


