class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        LIMIT = 10**18

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(LIMIT, fact[i - 1] * i)

        def count_completions(ro: int, re: int, last) -> int:
            m = ro + re
            if m == 0:
                return 1

            if last is None:
                patterns = 0

                # Start with odd.
                if ro == (m + 1) // 2 and re == m // 2:
                    patterns += 1

                # Start with even.
                if ro == m // 2 and re == (m + 1) // 2:
                    patterns += 1

                if patterns == 0:
                    return 0
                return min(LIMIT, patterns * fact[ro] * fact[re])

            # The next parity is forced.
            next_parity = 1 - last
            if next_parity == 1:  # next is odd
                need_ro = (m + 1) // 2
                need_re = m // 2
            else:                 # next is even
                need_ro = m // 2
                need_re = (m + 1) // 2

            if ro == need_ro and re == need_re:
                return min(LIMIT, fact[ro] * fact[re])
            return 0

        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        ro, re = len(odds), len(evens)

        if k > count_completions(ro, re, None):
            return []

        ans = []
        last = None

        for _ in range(n):
            if last is None:
                candidates = range(1, n + 1)
            else:
                required = 1 - last
                candidates = odds if required == 1 else evens

            for x in candidates:
                is_odd = (x % 2 == 1)
                new_ro = ro - (1 if is_odd else 0)
                new_re = re - (1 if not is_odd else 0)

                cnt = count_completions(new_ro, new_re, 1 if is_odd else 0)

                if k > cnt:
                    k -= cnt
                else:
                    ans.append(x)

                    if is_odd:
                        odds.remove(x)
                        ro = new_ro
                    else:
                        evens.remove(x)
                        re = new_re

                    last = 1 if is_odd else 0
                    break
            else:
                return []

        return ans

