from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        C = 4 * s

        # Clockwise perimeter coordinate in [0, 4*side).
        def perimeter(x: int, y: int) -> int:
            if y == 0:
                return x
            if x == s:
                return s + y
            if y == s:
                return 2 * s + (s - x)
            return 3 * s + (s - y)

        p = sorted(perimeter(x, y) for x, y in points)
        n = len(p)
        p2 = p + [v + C for v in p]

        limit = 2 * n
        steps = range(k - 1)

        def can(D: int) -> bool:
            if D == 0:
                return True
            # On a circle of circumference C, k points with mutual distance >= D
            # require k * D <= C.
            if D * k > C:
                return False

            # nxt[i] = first index j > i with p2[j] >= p2[i] + D
            nxt = [0] * limit
            j = 0
            pp = p2
            lim = limit

            for i in range(lim):
                if j < i:
                    j = i
                target = pp[i] + D
                while j < lim and pp[j] < target:
                    j += 1
                nxt[i] = j

            # If we start at i and greedily take k points, the last point must be
            # within C - D from the start so that the wrap-around gap is also >= D.
            max_span = C - D

            for i in range(n):
                idx = i
                for _ in steps:
                    idx = nxt[idx]
                    if idx >= lim:
                        break

                if idx < lim and pp[idx] <= pp[i] + max_span:
                    return True

            return False

        # For k >= 4, the answer never exceeds side. Also k * D <= 4 * side.
        lo, hi = 0, min(s, C // k)

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

