class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        stars = [i for i, ch in enumerate(p) if ch == '*']
        i, j = stars[0], stars[1]

        a = p[:i]
        b = p[i + 1:j]
        c = p[j + 1:]
        la, lb, lc = len(a), len(b), len(c)

        if la == 0 and lb == 0 and lc == 0:
            return 0

        def occurrences(text: str, pat: str):
            m = len(pat)
            n = len(text)
            if m == 0 or m > n:
                return []

            pi = [0] * m
            k = 0
            for idx in range(1, m):
                while k > 0 and pat[idx] != pat[k]:
                    k = pi[k - 1]
                if pat[idx] == pat[k]:
                    k += 1
                pi[idx] = k

            res = []
            k = 0
            for idx in range(n):
                while k > 0 and text[idx] != pat[k]:
                    k = pi[k - 1]
                if text[idx] == pat[k]:
                    k += 1
                if k == m:
                    res.append(idx - m + 1)
                    k = pi[k - 1]
            return res

        occ_a = occurrences(s, a) if la else []
        occ_b = occurrences(s, b) if lb else []
        occ_c = occurrences(s, c) if lc else []

        INF = 10 ** 18

        def min_two(occ1, l1, occ2, l2):
            if not occ1 or not occ2:
                return -1

            ans = INF
            min_possible = l1 + l2
            ptr = 0
            m2 = len(occ2)

            for start1 in occ1:
                need = start1 + l1
                while ptr < m2 and occ2[ptr] < need:
                    ptr += 1
                if ptr == m2:
                    break

                length = occ2[ptr] + l2 - start1
                if length < ans:
                    ans = length
                    if ans == min_possible:
                        return ans

            return -1 if ans == INF else ans

        def min_three(occA, la, occB, lb, occC, lc):
            if not occA or not occB or not occC:
                return -1

            ans = INF
            min_possible = la + lb + lc
            ptrA = 0
            bestA = -1
            ptrC = 0
            mA = len(occA)
            mC = len(occC)

            for startB in occB:
                limitA = startB - la
                while ptrA < mA and occA[ptrA] <= limitA:
                    bestA = occA[ptrA]
                    ptrA += 1

                if bestA == -1:
                    continue

                needC = startB + lb
                while ptrC < mC and occC[ptrC] < needC:
                    ptrC += 1
                if ptrC == mC:
                    break

                length = occC[ptrC] + lc - bestA
                if length < ans:
                    ans = length
                    if ans == min_possible:
                        return ans

            return -1 if ans == INF else ans

        if la == 0 and lb == 0:
            return lc if occ_c else -1
        if la == 0 and lc == 0:
            return lb if occ_b else -1
        if lb == 0 and lc == 0:
            return la if occ_a else -1

        if la == 0:
            return min_two(occ_b, lb, occ_c, lc)
        if lb == 0:
            return min_two(occ_a, la, occ_c, lc)
        if lc == 0:
            return min_two(occ_a, la, occ_b, lb)

        return min_three(occ_a, la, occ_b, lb, occ_c, lc)

