class Solution:
    def countSubstrings(self, s: str) -> int:
        # trans[d-1][digit][old_residue] = new_residue
        trans = [
            [[(a * 10 + digit) % d for a in range(d)] for digit in range(10)]
            for d in range(1, 10)
        ]
        # mod[d-1][digit] = digit % d
        mod = [[digit % d for digit in range(10)] for d in range(1, 10)]

        # freq[d-1][r] = number of substrings ending at the current position
        # whose numeric value is congruent to r modulo d.
        freq = [[0] * d for d in range(1, 10)]

        ans = 0

        for ch in s:
            x = ord(ch) - 48

            for i in range(9):
                d = i + 1
                old = freq[i]
                new = [0] * d
                t = trans[i][x]

                for a, c in enumerate(old):
                    if c:
                        new[t[a]] += c

                # Substring consisting of only the current digit.
                new[mod[i][x]] += 1
                freq[i] = new

            # Count only substrings whose last digit is non-zero.
            if x:
                ans += freq[x - 1][0]

        return ans

