        if blocks and L <= blocks[-1][1] + 1:
            blocks[-1][1] = R
        else:
            blocks.append([L, R])

    # A continuous bad block of length >= B cannot be crossed.
    for L, R in blocks:
        if R - L + 1 >= B:
            print("No")
            return

    # Safe components (maximal safe intervals).
    comps = []
    start = 1
    for L, R in blocks:
        if L > start:
            comps.append((start, L - 1))
        start = R + 1
    if start <= N:
        comps.append((start, N))

    K = len(comps)
    entry_masks = [0] * K
    entry_masks[0] = 1  # square 1 is reachable

    # Map each entry position (first min(B, length) squares of a component)
    # to (component_index, offset).  Offset fits in 5 bits because B <= 20.
    entry_map = {}
    for c, (S, T) in enumerate(comps):
        e_len = min(B, T - S + 1)
        base = c << 5
        for e in range(e_len):
            entry_map[S + e] = base | e

    bits = [1 << i for i in range(B)]

    # prev_masks[i]: bitmask of previous prefix indices that can reach index i.
    prev_masks = [0] * B
    for i in range(B):
        high = i - A
        if high >= 0:
            low = i - B
            if low < 0:
                low = 0
            width = high - low + 1
            prev_masks[i] = ((1 << width) - 1) << low

    # deltas[exit_len][e]: positive offsets from component end T
    # for jumps from the e-th exit position.
    deltas = [[[] for _ in range(B)] for _ in range(B + 1)]
    for exit_len in range(1, B + 1):
        for e in range(exit_len):
            x_offset = e - (exit_len - 1)  # x = T + x_offset
            for step in range(A, B + 1):
                d = x_offset + step
                if d > 0:
                    deltas[exit_len][e].append(d)

    # Boolean linear transition for one safe step.
    # State bit k (0=oldest) is reachability of position p-B+1+k.
    base_mat = [0] * B
    for j in range(B - 1):
        base_mat[j] = 1 << (j + 1)
    base_mat[B - 1] = (1 << (B - A + 1)) - 1

    max_log = N.bit_length() + 1
    mats = [base_mat]
    for _ in range(1, max_log):
        prev = mats[-1]
        cur = [0] * B
        for j in range(B):
            row = prev[j]
            res = 0
            r = row
            while r:
                lsb = r & -r
                i = lsb.bit_length() - 1
                res |= prev[i]
                r ^= lsb
            cur[j] = res
        mats.append(cur)

    def apply_power(mask: int, length: int) -> int:
        if mask == 0:
            return 0
        k = 0
        while length:
            if length & 1:
                mat = mats[k]
                new_mask = 0
                for j in range(B):
                    if mat[j] & mask:
                        new_mask |= bits[j]
                mask = new_mask
            length >>= 1
            k += 1
        return mask

    last = K - 1

    for c, (S, T) in enumerate(comps):
        in_mask = entry_masks[c]
        if in_mask == 0:
            continue

        length = T - S + 1
        prefix_len = B if length > B else length

        # Simulate the first min(B, length) positions exactly.
        dp_mask = 0
        for i in range(prefix_len):
            if ((in_mask >> i) & 1) or (dp_mask & prev_masks[i]):
                dp_mask |= 1 << i

        # State at position P = S + prefix_len - 1.
        state = dp_mask << (B - prefix_len)
        P = S + prefix_len - 1

        if T > P:
            state = apply_power(state, T - P)

        exit_len = B if length > B else length
        shift = 0 if length > B else (B - length)
        exit_mask = (state >> shift) & ((1 << exit_len) - 1)

        if c == last:
            if exit_mask & (1 << (exit_len - 1)):
                print("Yes")
                return
            continue

        if exit_mask == 0:
            continue

        # Jump from reachable exit positions to entry positions of future components.
        for e in range(exit_len):
            if (exit_mask >> e) & 1:
                for d in deltas[exit_len][e]:
                    y = T + d
                    if y > N:
                        break
                    val = entry_map.get(y)
                    if val is not None:
                        nc = val >> 5
                        if nc > c:
                            entry_masks[nc] |= 1 << (val & 31)
                            if nc == last and y == N:
                                print("Yes")
                                return

    print("No")


