    N, M = data[0], data[1]
    A = [0] + data[2:2 + N]
    MOD = 998244353

    children = [[] for _ in range(N + 1)]
    for i, a in enumerate(A[1:], 1):
        children[a].append(i)

    # Remove non-cycle nodes and compute subtree sizes.
    indeg = [len(children[i]) for i in range(N + 1)]
    q = [i for i in range(1, N + 1) if indeg[i] == 0]
    size = [1] * (N + 1)
    head = 0
    while head < len(q):
        u = q[head]
        head += 1
        p = A[u]
        size[p] += size[u]
        indeg[p] -= 1
        if indeg[p] == 0:
            q.append(p)

    in_cycle = [False] * (N + 1)
    for i in range(1, N + 1):
        if indeg[i] > 0:
            in_cycle[i] = True

    M1 = M + 1
    r = range(1, M1)
    mod = MOD
    base = list(range(M1))  # F_leaf[t] = t
    size_get = size.__getitem__

    sys.setrecursionlimit(1000000)

    def multiply_into(acc, f, r=r, mod=mod):
        acc[0] = 0
        for i in r:
            acc[i] = (acc[i] * f[i]) % mod

    def prefix_inplace(a, r=r, mod=mod):
        a[0] = 0
        s = 0
        for i in r:
            s += a[i]
            if s >= mod:
                s -= mod
            a[i] = s

    def calc(u, children=children, in_cycle=in_cycle, size_get=size_get,
             base=base, multiply_into=multiply_into, prefix_inplace=prefix_inplace):
        # Non-cycle node u: compute F_u[t] = #assignments in subtree with x_u <= t.
        ch = [v for v in children[u] if not in_cycle[v]]
        if not ch:
            return base

        # Process larger subtrees first to keep memory usage low.
        if len(ch) > 1:
            ch.sort(key=size_get, reverse=True)

        prod = None
        for v in ch:
            Fv = calc(v)
            if prod is None:
                if Fv is base:
                    Fv = Fv.copy()
                prod = Fv
            else:
                multiply_into(prod, Fv)
                Fv = None

        prefix_inplace(prod)
        return prod

    ans = 1
    visited = [False] * (N + 1)

    for i in range(1, N + 1):
        if in_cycle[i] and not visited[i]:
            comp = None
            cur = i

            while not visited[cur]:
                visited[cur] = True

                tree_ch = [v for v in children[cur] if not in_cycle[v]]
                if len(tree_ch) > 1:
                    tree_ch.sort(key=size_get, reverse=True)

                for v in tree_ch:
                    Fv = calc(v)
                    if comp is None:
                        if Fv is base:
                            Fv = Fv.copy()
                        comp = Fv
                    else:
                        multiply_into(comp, Fv)
                        Fv = None

                cur = A[cur]

            if comp is None:
                cnt = M % mod
            else:
                cnt = (sum(comp) - comp[0]) % mod

            ans = (ans * cnt) % mod

    print(ans)


