import sys


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    K = int(data[0])
    S = data[1]
    T = data[2]
    n = len(S)
    m = len(T)

    if abs(n - m) > K:
        print("No")
        return

    if S == T:
        print("Yes")
        return

    if K == 0:
        print("No")
        return

    if K >= max(n, m):
        print("Yes")
        return

    if n == 0:
        print("Yes" if m <= K else "No")
        return
    if m == 0:
        print("Yes" if n <= K else "No")
        return

    # Rolling hash (64-bit) is used only to get a good candidate LCP.
    # The candidate is verified exactly, so the LCP oracle is exact.
    MASK = (1 << 64) - 1
    BASE = 911382323

    max_len = max(n, m)
    powB = [1] * (max_len + 1)
    for i in range(1, max_len + 1):
        powB[i] = (powB[i - 1] * BASE) & MASK

    prefS = [0] * (n + 1)
    h = 0
    for i, b in enumerate(S):
        h = (h * BASE + b) & MASK
        prefS[i + 1] = h

    prefT = [0] * (m + 1)
    h = 0
    for i, b in enumerate(T):
        h = (h * BASE + b) & MASK
        prefT[i + 1] = h

    mvS = memoryview(S)
    mvT = memoryview(T)

    def lcp(i, j, n=n, m=m, prefS=prefS, prefT=prefT, powB=powB,
            MASK=MASK, mvS=mvS, mvT=mvT, S=S, T=T):
        if i < 0 or j < 0 or i > n or j > m:
            return 0

        max_l = n - i
        t = m - j
        if t < max_l:
            max_l = t
        if max_l <= 0:
            return 0

        if S[i] != T[j]:
            return 0
        if max_l == 1:
            return 1

        ps_i = prefS[i]
        pt_j = prefT[j]

        # Candidate from rolling hash.
        lo = 1
        hi = max_l
        while lo < hi:
            mid = (lo + hi + 1) >> 1
            h1 = (prefS[i + mid] - (ps_i * powB[mid] & MASK)) & MASK
            h2 = (prefT[j + mid] - (pt_j * powB[mid] & MASK)) & MASK
            if h1 == h2:
                lo = mid
            else:
                hi = mid - 1
        L = lo

        # Exact verification of the candidate.
        if L > 1 and mvS[i:i + L] != mvT[j:j + L]:
            lo = 1
            hi = L - 1
            while lo < hi:
                mid = (lo + hi + 1) >> 1
                if mvS[i:i + mid] == mvT[j:j + mid]:
                    lo = mid
                else:
                    hi = mid - 1
            return lo

        # If the next character also matches, the candidate was too small.
        if L < max_l and S[i + L] == T[j + L]:
            lo = L
            hi = max_l
            while lo < hi:
                mid = (lo + hi + 1) >> 1
                if mvS[i:i + mid] == mvT[j:j + mid]:
                    lo = mid
                else:
                    hi = mid - 1
            return lo

        return L

    # Landau-Vishkin style DP over edit count and diagonal.
    # Diagonal k = i - j.  prev[k] = furthest i reachable with <= d edits.
    x0 = lcp(0, 0)
    if x0 >= n and x0 >= m:
        print("Yes")
        return

    size = 2 * K + 5
    off = K + 2
    prev = [-1] * size
    prev[off] = x0

    for d in range(1, K + 1):
        curr = [-1] * size

        for k in range(-d, d + 1):
            idx = k + off
            xk = prev[idx]
            best = xk  # carry over states using fewer edits

            # Insertion: from diagonal k + 1, i unchanged.
            x = prev[idx + 1]
            if x >= 0:
                cand = x
                lim = m + k
                if cand > lim:
                    cand = lim
                if cand >= 0 and cand >= k:
                    if cand > best:
                        best = cand

            # Deletion: from diagonal k - 1, i increases by 1.
            x = prev[idx - 1]
            if x >= 0:
                cand = x + 1
                if cand > n:
                    cand = n
                if cand >= 0 and cand >= k and cand - k <= m:
                    if cand > best:
                        best = cand

            # Substitution: from diagonal k, i increases by 1.
            x = xk
            if x >= 0:
                cand = x + 1
                if cand > n:
                    cand = n
                lim = m + k
                if cand > lim:
                    cand = lim
                if cand >= 0 and cand >= k and cand - k <= m:
                    if cand > best:
                        best = cand

            if best >= 0:
                if best > n:
                    best = n
                j = best - k
                if j < 0 or j > m:
                    continue

                best += lcp(best, j)
                curr[idx] = best

                if best >= n and best - k >= m:
                    print("Yes")
                    return

        prev = curr

    print("No")


