        if not ints:
            continue
        ints.sort()
        cl, cr = ints[0]
        relevant = []
        for i in range(1, len(ints)):
            l, r = ints[i]
            if l <= cr:
                if r > cr:
                    cr = r
            else:
                cnt = br(houses_yx, (y, cr)) - bl(houses_yx, (y, cl))
                if cnt:
                    total += cnt
                    relevant.append((cl, cr))
                cl, cr = l, r
        cnt = br(houses_yx, (y, cr)) - bl(houses_yx, (y, cl))
        if cnt:
            total += cnt
            relevant.append((cl, cr))
        if relevant:
            merged_dict[y] = relevant
    return total, merged_dict

