from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        small = [x for x in nums if x <= T]
        large = len(nums) - len(small)

        if not small:
            return large
        if len(small) == 1 or 1 in small:
            return large + 1

        small.sort()
        limit = T + 1
        parent = list(range(limit))
        size = [1] * limit

        def find(x, parent=parent):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for a in small:
            start = a * 2
            if start >= limit:
                continue

            ra = find(a)
            for m in range(start, limit, a):
                rm = find(m)
                if ra != rm:
                    if size[ra] < size[rm]:
                        parent[ra] = rm
                        size[rm] += size[ra]
                        ra = rm
                    else:
                        parent[rm] = ra
                        size[ra] += size[rm]

        roots = set()
        for a in small:
            roots.add(find(a))

        return large + len(roots)
